import { cn } from '@/lib/utils'

/**
 * A country flag as a lazy-loaded static image (public/flags/<iso>.svg, ~0.6 KB
 * each, generated by scripts/build-flags.mjs). Nothing here is in the JS bundle,
 * only flags that scroll into view are fetched, and the fixed size avoids layout shift.
 */
export function Flag({ iso, className }: { iso: string; className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`/flags/${iso.toLowerCase()}.svg`}
      width={24}
      height={16}
      alt=""
      aria-hidden
      loading="lazy"
      decoding="async"
      className={cn('h-4 w-6 shrink-0 rounded-[3px] object-cover ring-1 ring-black/10', className)}
    />
  )
}
